import numpy as np
def solve(X,y,batch_size,seed=0):
 X,y=np.asarray(X),np.asarray(y)
 if len(X)!=len(y) or batch_size<=0: raise ValueError("input")
 idx=np.random.default_rng(seed).permutation(len(X)); return [(X[i],y[i]) for i in [idx[j:j+batch_size] for j in range(0,len(X),batch_size)]]

